"use strict";(self.webpackChunktmrw_help=self.webpackChunktmrw_help||[]).push([["5507"],{41622(e){e.exports=JSON.parse('{"version":{"pluginId":"fo","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"autogenerated":[{"type":"link","href":"/fo/Overview","label":"Finance and Operations \u2013 User Guide","docId":"Overview","unlisted":false},{"type":"link","href":"/fo/","label":"Finance & Operations Help","docId":"index","unlisted":false},{"type":"link","href":"/fo/Navigating-the-Platform","label":"Navigating the F&O Platform","docId":"Navigating-the-Platform","unlisted":false},{"type":"link","href":"/fo/Setup","label":"Setup","docId":"Setup","unlisted":false},{"type":"link","href":"/fo/Debtor-Management","label":"Debtor Management","docId":"Debtor-Management","unlisted":false},{"type":"link","href":"/fo/Billing","label":"Billing","docId":"Billing","unlisted":false},{"type":"category","label":"Billing","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/fo/billing/create-a-fee-schedule-template","label":"Create a fee schedule template","docId":"billing/create-a-fee-schedule-template","unlisted":false}]},{"type":"link","href":"/fo/Pre-Admission-Fees","label":"Pre\u2011Admission Fees","docId":"Pre-Admission-Fees","unlisted":false},{"type":"category","label":"Concession Management","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/fo/Concession-Management/approve-or-reject-discount","label":"Approve or Reject a Discount","docId":"Concession-Management/approve-or-reject-discount","unlisted":false},{"type":"link","href":"/fo/Concession-Management/configure-sibling-discount-policy","label":"configure-sibling-discount-policy","docId":"Concession-Management/configure-sibling-discount-policy","unlisted":false},{"type":"link","href":"/fo/Concession-Management/create-a-scholarship-or-discount","label":"Create a Scholarship or Discount","docId":"Concession-Management/create-a-scholarship-or-discount","unlisted":false},{"type":"link","href":"/fo/Concession-Management/import-scholarships-discounts-excel","label":"Import Scholarship and Discount Data via Excel","docId":"Concession-Management/import-scholarships-discounts-excel","unlisted":false},{"type":"link","href":"/fo/Concession-Management/link-discount-to-fee-items","label":"Link a Discount to Fee Items","docId":"Concession-Management/link-discount-to-fee-items","unlisted":false},{"type":"link","href":"/fo/Concession-Management/link-discount-to-student","label":"Link a Discount to a Student","docId":"Concession-Management/link-discount-to-student","unlisted":false},{"type":"link","href":"/fo/Concession-Management/set-up-charge-code","label":"Set Up a Charge Code","docId":"Concession-Management/set-up-charge-code","unlisted":false},{"type":"link","href":"/fo/Concession-Management/set-up-staff-concession-code","label":"Set Up a Staff Concession Code","docId":"Concession-Management/set-up-staff-concession-code","unlisted":false},{"type":"link","href":"/fo/Concession-Management/verify-concession-in-sales-order","label":"Verify a Concession in a Sales Order","docId":"Concession-Management/verify-concession-in-sales-order","unlisted":false},{"type":"link","href":"/fo/Concession-Management/view-approved-discount-fees","label":"View Approved Discount Fees on a Batch","docId":"Concession-Management/view-approved-discount-fees","unlisted":false},{"type":"link","href":"/fo/Concession-Management/view-student-discounts","label":"View a Student\'s Scholarships and Discounts","docId":"Concession-Management/view-student-discounts","unlisted":false}],"href":"/fo/Concession-Management/"},{"type":"link","href":"/fo/Concession-Management","label":"Concession Management","docId":"Concession-Management","unlisted":false},{"type":"link","href":"/fo/Visa-Management","label":"Visa Management","docId":"Visa-Management","unlisted":false},{"type":"link","href":"/fo/Subject-&-Event-Management","label":"Subject & Event Management","docId":"Subject-&-Event-Management","unlisted":false},{"type":"link","href":"/fo/Student-Promotion","label":"Student Promotion","docId":"Student-Promotion","unlisted":false},{"type":"link","href":"/fo/Collections","label":"Collections","docId":"Collections","unlisted":false},{"type":"link","href":"/fo/Inquiries-and-Reports","label":"Inquiry & Reports","docId":"Inquiries-and-Reports","unlisted":false},{"type":"link","href":"/fo/Debt-Follow-Up","label":"Debt Follow-up","docId":"Debt-Follow-Up","unlisted":false},{"type":"link","href":"/fo/Cash-&-Bank","label":"Cash & Bank","docId":"Cash-&-Bank","unlisted":false},{"type":"link","href":"/fo/Intercompany-Transactions","label":"Intercompany Transactions","docId":"Intercompany-Transactions","unlisted":false},{"type":"link","href":"/fo/Revenue-Recognition","label":"Revenue Recognition","docId":"Revenue-Recognition","unlisted":false},{"type":"link","href":"/fo/FAQs","label":"Frequently Asked Questions","docId":"FAQs","unlisted":false},{"type":"link","href":"/fo/Glossary","label":"Glossary","docId":"Glossary","unlisted":false},{"type":"link","href":"/fo/Brendan","label":"Brendan","docId":"Brendan","unlisted":false},{"type":"link","href":"/fo/Dana","label":"Dana","docId":"Dana","unlisted":false},{"type":"link","href":"/fo/Hoda","label":"Hoda","docId":"Hoda","unlisted":false}]},"docs":{"Billing":{"id":"Billing","title":"Billing","description":"Billing manages the end-to-end process of generating and posting fee invoices for students. It covers the creation of fee schedule templates that define what is charged and when, running batch jobs to generate sales orders across a student cohort, posting invoices by term, and handling adjustments for students who join or leave mid-term through pro rata calculations. Split billing configurations, proforma invoice generation and distribution, advance tax invoice requests, fee structure pricing through trade agreements, and student ledger reporting are also handled here.","sidebar":"autogenerated"},"billing/create-a-fee-schedule-template":{"id":"billing/create-a-fee-schedule-template","title":"Create a fee schedule template","description":"Fee schedule templates define what is charged to students and when. Each","sidebar":"autogenerated"},"Brendan":{"id":"Brendan","title":"Brendan","description":"","sidebar":"autogenerated"},"Cash-&-Bank":{"id":"Cash-&-Bank","title":"Cash & Bank","description":"Cash & Bank covers the day-end procedures and bank reconciliation processes required to close out daily transactions accurately. Staff consolidate individual deposit slips created across the day into a single deposit slip by payment method, generate a combined deposit slip report for banking purposes, and verify the resulting entries against the bank account transaction view. These procedures ensure that cash received through counter payments and other channels is correctly recorded and reconciled at the close of each business day.","sidebar":"autogenerated"},"Collections":{"id":"Collections","title":"Collections","description":"Collections covers the full range of payment processing and receipt management functions available to finance staff. It includes setting up and applying payment plans for instalment arrangements, processing in-person payments through over-the-counter and cashier receipt forms, handling post-dated cheques and overpayments, scheduling bulk credit card payment runs, processing advance payments with discount calculations, managing early payment discounts, issuing fee refunds of credit balances, recording miscellaneous receipts, reversing posted payments, and handling dishonoured cheques.","sidebar":"autogenerated"},"Concession-Management":{"id":"Concession-Management","title":"Concession Management","description":"Concession Management handles the configuration and application of scholarships, discounts, and staff concessions across the fee management system. Scholarship and discount codes are created, linked to fee items and students, and moved through an approval workflow before taking effect. Staff concessions are managed through dedicated charge codes in the auto charges table, with separate discount codes configured for each concession type. Applied discounts can be reviewed directly against fee schedule batches once invoices are generated. For high-volume setup, bulk import of scholarship and discount records is supported through the Microsoft Excel add-in.","sidebar":"autogenerated"},"Concession-Management/approve-or-reject-discount":{"id":"Concession-Management/approve-or-reject-discount","title":"Approve or Reject a Discount","description":"1. Open Scholarships and Discounts","sidebar":"autogenerated"},"Concession-Management/configure-sibling-discount-policy":{"id":"Concession-Management/configure-sibling-discount-policy","title":"configure-sibling-discount-policy","description":"{/ GEMS: review destination /}","sidebar":"autogenerated"},"Concession-Management/create-a-scholarship-or-discount":{"id":"Concession-Management/create-a-scholarship-or-discount","title":"Create a Scholarship or Discount","description":"Before a scholarship or discount takes effect on a student\'s fees, it must be created as a named code, linked to the relevant fee items and students, and moved through the approval workflow.","sidebar":"autogenerated"},"Concession-Management/import-scholarships-discounts-excel":{"id":"Concession-Management/import-scholarships-discounts-excel","title":"Import Scholarship and Discount Data via Excel","description":"Use this process to enter or update scholarship and discount records in bulk using the Microsoft Excel add-in, rather than creating records one at a time in the interface.","sidebar":"autogenerated"},"Concession-Management/index":{"id":"Concession-Management/index","title":"Concession Management","description":"Concession Management covers the configuration and application of scholarships, discounts, and staff concessions across the fee management system. Codes are created, linked to fee items and students, and moved through an approval workflow before the system applies them automatically when invoices are generated. Bulk import via the Microsoft Excel add-in is available for high-volume setup.","sidebar":"autogenerated"},"Concession-Management/link-discount-to-fee-items":{"id":"Concession-Management/link-discount-to-fee-items","title":"Link a Discount to Fee Items","description":"Fee items must be linked to a scholarship or discount code before the discount applies when invoices are generated.","sidebar":"autogenerated"},"Concession-Management/link-discount-to-student":{"id":"Concession-Management/link-discount-to-student","title":"Link a Discount to a Student","description":"1. Open Scholarships and Discounts","sidebar":"autogenerated"},"Concession-Management/set-up-charge-code":{"id":"Concession-Management/set-up-charge-code","title":"Set Up a Charge Code","description":"Staff concession discounts are applied to fee invoices through the auto charges table. A charge code defines how and where the concession amount posts in the ledger. Create one charge code per concession type \u2014 for example, separate codes for staff concessions and commercial concessions.","sidebar":"autogenerated"},"Concession-Management/set-up-staff-concession-code":{"id":"Concession-Management/set-up-staff-concession-code","title":"Set Up a Staff Concession Code","description":"Before using this page, ensure a charge code has been created and is ready to link. See Set Up a Charge Code.","sidebar":"autogenerated"},"Concession-Management/verify-concession-in-sales-order":{"id":"Concession-Management/verify-concession-in-sales-order","title":"Verify a Concession in a Sales Order","description":"Use this process to generate a concession estimate for a student, run the fee batch for that student, and confirm the discount has applied correctly on the resulting sales order.","sidebar":"autogenerated"},"Concession-Management/view-approved-discount-fees":{"id":"Concession-Management/view-approved-discount-fees","title":"View Approved Discount Fees on a Batch","description":"1. Open All Fee Schedule Batches","sidebar":"autogenerated"},"Concession-Management/view-student-discounts":{"id":"Concession-Management/view-student-discounts","title":"View a Student\'s Scholarships and Discounts","description":"1. Open the student record","sidebar":"autogenerated"},"Dana":{"id":"Dana","title":"Dana","description":"Post Fee Invoices","sidebar":"autogenerated"},"Debt-Follow-Up":{"id":"Debt-Follow-Up","title":"Debt Follow-up","description":"Debt Follow-Up supports the management and resolution of outstanding student balances. It covers processes for customer write-back, bulk write-off of unrecoverable debts, debt classification, and the use of Excel upload options to manage excluded students or update debt records in bulk. These tools allow finance teams to maintain accurate accounts receivable records and manage aged debt in a structured and auditable way.","sidebar":"autogenerated"},"Debtor-Management":{"id":"Debtor-Management","title":"Debtor Management","description":"Debtor Management covers the student and fee payer record management that underpins accurate fee generation. It includes verifying that each student has the correct academic year, enrolment dates, and sibling order assigned before any fee batch is run, and confirming that financial responsibility percentages across all fee payers on a student\'s account total 100. It also covers the setup of split financial responsibility, allowing schools to define default billing percentages across multiple fee payers such as parents or guardians. Any errors in this data at the debtor level flow directly through to generated invoices, making this a critical step before running any billing cycle.","sidebar":"autogenerated"},"FAQs":{"id":"FAQs","title":"Frequently Asked Questions","description":"---","sidebar":"autogenerated"},"Glossary":{"id":"Glossary","title":"Glossary","description":"| Term | Definition |","sidebar":"autogenerated"},"Hoda":{"id":"Hoda","title":"Hoda","description":"","sidebar":"autogenerated"},"index":{"id":"index","title":"Finance & Operations Help","description":"Welcome to the Finance & Operations (F&O) help centre. F&O covers billing, fee management, debtor management, and financial operations for bursars and accountants.","sidebar":"autogenerated"},"Inquiries-and-Reports":{"id":"Inquiries-and-Reports","title":"Inquiry & Reports","description":"Inquiries and Reports gives finance and administration staff direct access to key student and family financial data within Academic Management. It includes reports for identifying the eldest child in a family, calculating the number of siblings per family, and viewing other student and family-level financial information used to support sibling discount processing and fee payer management.","sidebar":"autogenerated"},"Intercompany-Transactions":{"id":"Intercompany-Transactions","title":"Intercompany Transactions","description":"The intercompany transfer process is used when a student moves from one school to another and holds a credit balance in the originating school\'s system. Finance staff transfer that credit balance to the destination school so it can be applied to the student\'s account there. Before a transfer can be processed, any advanced tax invoices \u2014 such as those raised for application fees or enrolment deposits \u2014 must be cancelled, as the system only supports the transfer of net credit balances. The system identifies the student across both schools using a shared global Party ID, and automatically generates paired transfer journals in both the originating and destination schools upon completion. A separate intercompany channel setup controls the accounts, journal names, and posting profiles used for these transfer entries.","sidebar":"autogenerated"},"Navigating-the-Platform":{"id":"Navigating-the-Platform","title":"Navigating the F&O Platform","description":"Basic Navigation in F&O","sidebar":"autogenerated"},"Overview":{"id":"Overview","title":"Finance and Operations \u2013 User Guide","description":"Version: v3","sidebar":"autogenerated"},"Pre-Admission-Fees":{"id":"Pre-Admission-Fees","title":"Pre\u2011Admission Fees","description":"Before any pre-admission fees can be processed, the system needs to be configured with the correct transaction types and posting logic. This involves defining the categories of fees that will be charged prior to enrolment, such as application fees, enrolment fees, and enrolment deposits, and mapping each of these to the appropriate general ledger accounts. Without this setup in place, the system will not know how to record or post these transactions correctly. Fee schedule parameters also need to be updated to enable pre-admission processing across the platform.","sidebar":"autogenerated"},"Revenue-Recognition":{"id":"Revenue-Recognition","title":"Revenue Recognition","description":"Revenue Recognition manages the month-end process of recognising deferred revenue in line with the school\'s billing and deferral schedule configuration. It allows finance staff to run recognition processing across all eligible deferral schedules for a given period using the Periodic tasks batch process, or to process recognition for a single invoice directly from the Deferral schedules list. Correct configuration of cutoff dates and transaction dates ensures that revenue is posted to the appropriate general ledger accounts for the period being closed.","sidebar":"autogenerated"},"Setup":{"id":"Setup","title":"Setup","description":"Before fees can be generated, processed, or settled across the platform, a range of foundational settings must be configured correctly. This section covers the full scope of that setup work, including fee schedule parameters, fee and charge intervals, gender and academic year configuration, visa types, split billing percentages, fee categories, payment option setup, curriculum and stream configuration, advanced discount policies, deposit policies, sibling order and trade agreement setup, non-tuition item pricing, and the linkage of tuition fee items to academic years. Most of this configuration is completed once during initial implementation and revisited when new functionality is enabled or organisational settings change.","sidebar":"autogenerated"},"Student-Promotion":{"id":"Student-Promotion","title":"Student Promotion","description":"Student Promotion manages the financial checks and processes for students moving between academic years. It covers how the system automatically polls outstanding fee balances during re-enrolment periods and blocks students from progressing if they exceed a configured threshold. Staff can review blocked students, arrange payment with families, and apply financial check overrides with an audit reason where a payment arrangement is in place. Financial obligations are reviewed and resolved before re-enrolment invitations are issued.","sidebar":"autogenerated"},"Subject-&-Event-Management":{"id":"Subject-&-Event-Management","title":"Subject & Event Management","description":"Subject & Event Management handles the setup and invoicing of fee-generating activities including excursions, music lessons, and other school events. Fee categories, subject and event codes, and event fee schedule templates are configured before students are enrolled into sessional classes or events. Invoicing can be set to charge a flat fee or calculated based on the number of sessions attended using session-based invoicing. Where session numbers change after invoices have been generated, adjustment processing is available to keep student accounts accurate. Enrolment cancellations are also managed here.","sidebar":"autogenerated"},"Visa-Management":{"id":"Visa-Management","title":"Visa Management","description":"Visa Management keeps student visa records accurate and accessible within the Academic Management system. While visa entries are typically created automatically through the Customer Engagement (CE) integration, staff can also create and maintain visa types manually when required. Visa details are viewable directly on individual student records, and a dedicated report provides a full list of students with active visas across the school. Keeping this information current supports compliance obligations and gives the school a clear picture of its international student cohort.","sidebar":"autogenerated"}}}}')}}]);